+/*
+ * SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ * SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#include "chargelimitcontrol.h"
+
+#include "batterymonitor_debug.h"
+
+#include <QDBusConnection>
+#include <QDBusConnectionInterface>
+#include <QDBusMessage>
+#include <QDBusPendingCallWatcher>
+#include <QDBusPendingReply>
+#include <QDBusServiceWatcher>
+
+static constexpr QLatin1StringView SOLID_POWERMANAGEMENT_SERVICE("org.kde.Solid.PowerManagement");
+static constexpr QLatin1StringView SOLID_POWERMANAGEMENT_PATH("/org/kde/Solid/PowerManagement");
+static constexpr QLatin1StringView SOLID_POWERMANAGEMENT_IFACE("org.kde.Solid.PowerManagement");
+
+ChargeLimitControl::ChargeLimitControl(QObject *parent)
+    : QObject(parent)
+    , m_solidWatcher(new QDBusServiceWatcher)
+{
+    m_solidWatcher->setConnection(QDBusConnection::sessionBus());
+    m_solidWatcher->setWatchMode(QDBusServiceWatcher::WatchForRegistration | QDBusServiceWatcher::WatchForUnregistration);
+    m_solidWatcher->addWatchedService(SOLID_POWERMANAGEMENT_SERVICE);
+
+    connect(m_solidWatcher.get(), &QDBusServiceWatcher::serviceRegistered, this, &ChargeLimitControl::onServiceRegistered);
+    connect(m_solidWatcher.get(), &QDBusServiceWatcher::serviceUnregistered, this, &ChargeLimitControl::onServiceUnregistered);
+
+    if (QDBusConnection::sessionBus().interface()->isServiceRegistered(SOLID_POWERMANAGEMENT_SERVICE)) {
+        onServiceRegistered();
+    }
+}
+
+ChargeLimitControl::~ChargeLimitControl()
+{
+}
+
+bool ChargeLimitControl::isChargingFullyOnce() const
+{
+    return m_chargingFullyOnce;
+}
+
+void ChargeLimitControl::setChargingFullyOnce(bool enabled)
+{
+    QDBusMessage message = QDBusMessage::createMethodCall(SOLID_POWERMANAGEMENT_SERVICE,
+                                                          SOLID_POWERMANAGEMENT_PATH,
+                                                          SOLID_POWERMANAGEMENT_IFACE,
+                                                          QStringLiteral("setChargingFullyOnce"));
+    message << enabled;
+    QDBusConnection::sessionBus().asyncCall(message);
+}
+
+void ChargeLimitControl::onServiceRegistered()
+{
+    QDBusMessage message = QDBusMessage::createMethodCall(SOLID_POWERMANAGEMENT_SERVICE,
+                                                          SOLID_POWERMANAGEMENT_PATH,
+                                                          SOLID_POWERMANAGEMENT_IFACE,
+                                                          QStringLiteral("isChargingFullyOnce"));
+    auto watcher = new QDBusPendingCallWatcher(QDBusConnection::sessionBus().asyncCall(message), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *watcher) {
+        QDBusPendingReply<bool> reply = *watcher;
+        if (reply.isValid()) {
+            updateChargingFullyOnce(reply.value());
+        } else {
+            qCDebug(APPLETS::BATTERYMONITOR) << "error getting whether the battery is charging fully once";
+        }
+        watcher->deleteLater();
+    });
+
+    if (!QDBusConnection::sessionBus().connect(SOLID_POWERMANAGEMENT_SERVICE,
+                                               SOLID_POWERMANAGEMENT_PATH,
+                                               SOLID_POWERMANAGEMENT_IFACE,
+                                               QStringLiteral("chargingFullyOnceChanged"),
+                                               this,
+                                               SLOT(updateChargingFullyOnce(bool)))) {
+        qCDebug(APPLETS::BATTERYMONITOR) << "error connecting to charging fully once changes via dbus";
+    }
+}
+
+void ChargeLimitControl::onServiceUnregistered()
+{
+    QDBusConnection::sessionBus().disconnect(SOLID_POWERMANAGEMENT_SERVICE,
+                                             SOLID_POWERMANAGEMENT_PATH,
+                                             SOLID_POWERMANAGEMENT_IFACE,
+                                             QStringLiteral("chargingFullyOnceChanged"),
+                                             this,
+                                             SLOT(updateChargingFullyOnce(bool)));
+    updateChargingFullyOnce(false);
+}
+
+void ChargeLimitControl::updateChargingFullyOnce(bool enabled)
+{
+    if (m_chargingFullyOnce == enabled) {
+        return;
+    }
+    m_chargingFullyOnce = enabled;
+    Q_EMIT chargingFullyOnceChanged(enabled);
+}
+
+#include "moc_chargelimitcontrol.cpp"
