@@ -0,0 +1,95 @@
+/*
+ * SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ * SPDX-License-Identifier: GPL-2.0-only OR GPL-3.0-only OR LicenseRef-KDE-Accepted-GPL
+ */
+
+#include "chargethresholdhelper.h"
+
+#include <QDir>
+#include <QFile>
+#include <QFileInfo>
+
+using namespace Qt::StringLiterals;
+
+// Kept outside of the session so that the configured limits survive a reboot while charging fully once
+static const QString s_thresholdsBeforeFullChargePath = u"/var/lib/powerdevil/charge-thresholds-before-full-charge"_s;
+
+bool ChargeThresholdHelper::isChargingFullyOnce()
+{
+    return QFile::exists(s_thresholdsBeforeFullChargePath);
+}
+
+void ChargeThresholdHelper::forgetThresholdsBeforeFullCharge()
+{
+    QFile::remove(s_thresholdsBeforeFullChargePath);
+}
+
+ActionReply ChargeThresholdHelper::chargefullyonce(const QVariantMap &args)
+{
+    Q_UNUSED(args);
+
+    if (isChargingFullyOnce()) {
+        return ActionReply();
+    }
+
+    const ActionReply current = getthreshold({});
+    if (current.failed()) {
+        return current;
+    }
+
+    const int startThreshold = current.data().value(u"chargeStartThreshold"_s).toInt();
+    const int stopThreshold = current.data().value(u"chargeStopThreshold"_s).toInt();
+    if (stopThreshold == 100) {
+        return ActionReply();
+    }
+
+    QVariantMap fullCharge{{u"chargeStopThreshold"_s, 100}};
+    if (startThreshold != -1) {
+        fullCharge.insert(u"chargeStartThreshold"_s, 0);
+    }
+
+    if (const ActionReply reply = setthreshold(fullCharge); reply.failed()) {
+        return reply;
+    }
+
+    QDir().mkpath(QFileInfo(s_thresholdsBeforeFullChargePath).path());
+    QFile file(s_thresholdsBeforeFullChargePath);
+    if (!file.open(QIODevice::WriteOnly) || file.write(QByteArray::number(startThreshold) + ' ' + QByteArray::number(stopThreshold)) == -1) {
+        file.close();
+        file.remove();
+        setthreshold({{u"chargeStartThreshold"_s, startThreshold}, {u"chargeStopThreshold"_s, stopThreshold}});
+        auto reply = ActionReply::HelperErrorReply();
+        reply.setErrorDescription(u"Failed to remember the charge thresholds"_s);
+        return reply;
+    }
+
+    return ActionReply();
+}
+
+ActionReply ChargeThresholdHelper::restorethreshold(const QVariantMap &args)
+{
+    Q_UNUSED(args);
+
+    QFile file(s_thresholdsBeforeFullChargePath);
+    if (!file.open(QIODevice::ReadOnly)) {
+        return ActionReply();
+    }
+
+    const QList<QByteArray> thresholds = file.readAll().split(' ');
+    file.close();
+
+    bool startOk = false;
+    bool stopOk = false;
+    const int startThreshold = thresholds.value(0).toInt(&startOk);
+    const int stopThreshold = thresholds.value(1).toInt(&stopOk);
+    if (!startOk || !stopOk) {
+        forgetThresholdsBeforeFullCharge();
+        auto reply = ActionReply::HelperErrorReply();
+        reply.setErrorDescription(u"Invalid saved charge thresholds"_s);
+        return reply;
+    }
+
+    // Removes the saved thresholds once they are applied again
+    return setthreshold({{u"chargeStartThreshold"_s, startThreshold}, {u"chargeStopThreshold"_s, stopThreshold}});
+}
